package rules; import core.PortRange; public final class PortExpression{private final String raw;private final boolean negated;private final PortRange range;public PortExpression(String raw){String s=raw==null?"any":raw.trim();this.negated=s.startsWith("!");if(negated)s=s.substring(1);this.raw=raw==null?"any":raw.trim();PortRange r;try{r=PortRange.parse(s.replace("[","").replace("]","").replace(",","-"));}catch(Exception e){r=PortRange.any();}this.range=r;}public boolean matches(int port){boolean m=range.contains(port<0?0:port);return negated?!m:m;}public String raw(){return raw;}public String normalized(){return raw.toLowerCase(java.util.Locale.ROOT);}}
